def transform(grid):
    """Transform task-task-bebb318c demo and test grids."""

    def transform_row(row):
        # Rule: When first 3 columns have all same non-zero value X, 
        # change that value to 8 at columns divisible by 6
        if any(v == 0 for v in row[:3]):
            return row[:]  # No transform if first 3 cols have zeros
        else:
            # All first 3 are the same non-zero value
            return [0 if v == 0 else 8 if j % 6 == 0 else v for j, v in enumerate(row)]

    return [transform_row(row) for row in grid]

